package factory

import (
	"context"
	"path"
	"strings"

	authored "github.com/dsx-ai-factory/nvkr/pkg/nvkr/definition"
	e "github.com/dsx-ai-factory/nvkr/pkg/nvkr/errors"
)

// CheckGitHubRuntimeInputs checks a delivered runtime bundle against the current
// checkout's authored selection and complete generated bytes. It performs no
// compilation, catalog access, execution or writes, and issues no authority receipt.
func CheckGitHubRuntimeInputs(ctx context.Context, plan *Plan, root string) error {
	if err := admitGitHubRuntimeInputs(ctx, plan, root); err != nil {
		return err
	}
	if plan.Environment.GitHubRuntimeSource != nil && plan.RuntimeSourceCommit == "" {
		return e.New(e.CodeUnpinnedSource, "runtime source inputs omit the frozen commit")
	}
	if err := checkGitHubRuntimeAuthoredInputs(ctx, plan, root); err != nil {
		return err
	}
	bundle, err := RenderGitHub(ctx, plan)
	if err != nil {
		return err
	}
	return CheckGeneratedBundle(ctx, root, bundle)
}

func admitGitHubRuntimeInputs(ctx context.Context, plan *Plan, root string) error {
	if ctx == nil || plan == nil || strings.TrimSpace(root) == "" {
		return e.New(e.CodeUsage, "runtime GitHub input check requires context, Plan and repository root")
	}
	if err := ctx.Err(); err != nil {
		return e.Wrap(e.CodeTimeout, err, "runtime GitHub input check canceled")
	}
	if !plan.Environment.GitHubRuntimePlan || plan.Environment.GitHubBundle == "" || plan.Environment.GitHubDevelopment {
		return e.New(e.CodeEngineCapability, "runtime GitHub input check requires an opted-in named production bundle")
	}
	if err := plan.Validate(); err != nil {
		return err
	}
	return nil
}

func checkGitHubRuntimeAuthoredInputs(ctx context.Context, plan *Plan, root string) error {
	for _, name := range []string{plan.DefinitionPath, plan.EnvironmentPath} {
		if err := validateInputPath(name); err != nil {
			return err
		}
		if err := validateGeneratedDirectoryChain(root, path.Dir(name)); err != nil {
			return e.Wrap(e.CodePipelineDrift, err, "runtime GitHub authored input %s has unsafe parents", name)
		}
	}
	definitionPath, err := generatedDestination(root, plan.DefinitionPath)
	if err != nil {
		return err
	}
	environmentPath, err := generatedDestination(root, plan.EnvironmentPath)
	if err != nil {
		return err
	}
	definition, err := authored.LoadDefinition(ctx, definitionPath)
	if err != nil {
		return err
	}
	environment, err := authored.LoadEnvironment(ctx, environmentPath)
	if err != nil {
		return err
	}
	definitionDigest, err := definition.Digest()
	if err != nil {
		return err
	}
	environmentDigest, err := environment.Digest()
	if err != nil {
		return err
	}
	if definitionDigest != plan.DefinitionDigest || environmentDigest != plan.EnvironmentDigest {
		return e.New(e.CodePipelineDrift, "runtime GitHub inputs do not bind the checkout's current Definition and Environment")
	}
	return nil
}
